import{E as e,d as t,l as n}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as r}from"./app-C3QVrxQ1.js";var i=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S01/S01E17.html","title":"S01E17 The One with Two Parts: Part 2","lang":"zh-CN","frontmatter":{"title":"S01E17 The One with Two Parts: Part 2","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":17},"git":{"createdTime":1780654155000,"updatedTime":1780654155000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":41.07,"words":12321},"filePathRelative":"语言/英语/Friends老友记/S01/S01E17.md"}`),a={name:`S01E17.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t('<h1 id="the-one-with-two-parts-part-2" tabindex="-1"><a class="header-anchor" href="#the-one-with-two-parts-part-2"><span>The One with Two Parts: Part 2</span></a></h1><blockquote><p><em>有两部分的那一部分：第2部分</em></p></blockquote><p>The One With Two Parts, Part 2</p><blockquote><p>一个有两个部分，第二部分</p></blockquote><p><strong>Written by: Marta Kauffman &amp; David Crane</strong></p><blockquote><p>作者：Marta Kauffman和David Crane</p></blockquote><p><strong>Transcribed by: Mindy Mattingly</strong></p><blockquote><p>转录人：Mindy Mattingly</p></blockquote><p><strong>With Minor Adjustments by:</strong> Tennant Stuart</p><blockquote><p>坦南特·斯图尔特</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>An Emergency Room, Rachel and Monica enter. Rachel is limping and leaning on Monica for support.</em></p><blockquote><p>🎬 <em>急诊室，瑞秋和莫妮卡进入。瑞秋一瘸一拐地靠在莫妮卡身上寻求支持。</em></p></blockquote><p><strong>Rachel Green:</strong> Ow ow ow. Ow ow ow ow. Ow ow ow. Ow. Ow. Ow. Ow.</p><blockquote><p>噢。哎哟。哎哟。噢噢噢噢</p></blockquote><p><em>(They reach the desk. The bored nurse thinks she&#39;s heard it all before.)</em></p><blockquote><p><em>（他们走到办公桌前。无聊的护士认为她以前都听说过。）</em></p></blockquote><p><strong>Monica Geller:</strong> Hi. Uh, my friend here was taking down our Christmas lights, and and she fell off the balcony and may have broken her foot or or ankle or something.</p><blockquote><p>嗨。呃，我的朋友在这里取下我们的圣诞灯，她从阳台上摔了下来，可能摔断了脚或脚踝什么的。</p></blockquote><p><strong>Nurse:</strong> My god. You still have your Christmas lights up?</p><blockquote><p>天哪。你的圣诞灯还亮着吗？</p></blockquote><p><em>(Rachel glares at the nurse, who gives Monica a form attached to a clipboard.)</em></p><blockquote><p><em>（瑞秋怒视着护士，护士给莫妮卡一张附在剪贴板上的表格。）</em></p></blockquote><p><strong>Nurse:</strong> Fill this out and bring it back to me.</p><blockquote><p>填好这个，然后拿给我。</p></blockquote><p><em>(Monica helps Rachel over to a vacant seat.)</em></p><blockquote><p><em>（莫妮卡帮瑞秋找到一个空座位。）</em></p></blockquote><p><strong>Rachel Green:</strong> Ow ow ow. Ow ow ow. Ow ow ow.</p><blockquote><p>噢。哎哟。哎哟。</p></blockquote><p><em>(Monica starts on the form, while Rachel catches her breath and massages her ankle.)</em></p><blockquote><p><em>（莫妮卡从表格开始，瑞秋屏住呼吸，按摩脚踝。）</em></p></blockquote><p><strong>Monica Geller:</strong> Okay, ooh, alright. Name, address... Okay, in case of emergency, call?</p><blockquote><p>好的，哦，好的。姓名、地址……好的，如果有紧急情况，打电话？</p></blockquote><p><strong>Rachel Green:</strong> You.</p><blockquote><p>你。</p></blockquote><p><strong>Monica Geller:</strong> Really?</p><blockquote><p>真的吗？</p></blockquote><p><strong>Rachel Green:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>Monica Geller:</strong> Oh, that is so sweet. (Touched, she puts an arm around her friend and kisses her.) Oh gosh, love you. Insurance?</p><blockquote><p>哦，太好了。（被感动了，她伸出一只手臂搂住她的朋友并吻了她。）哦，天哪，我爱你。保险？</p></blockquote><p><strong>Rachel Green:</strong> Oh, yeah, check it. Definitely, I want some of that.</p><blockquote><p>哦，是的，检查一下。当然，我想要一些。</p></blockquote><p><strong>Monica Geller:</strong> (No longer touched) you don&#39;t have insurance?</p><blockquote><p>（不再碰）你没有保险？</p></blockquote><p><strong>Rachel Green:</strong> Why, how much is this gonna cost?</p><blockquote><p>为什么，这要花多少钱？</p></blockquote><p><strong>Monica Geller:</strong> I have no idea, but X-rays alone could be a couple hundred dollars.</p><blockquote><p>我不知道，但光是X光片就要几百美元。</p></blockquote><p><strong>Rachel Green:</strong> Wel-wel-well what are we gonna do?</p><blockquote><p>我们该怎么办？</p></blockquote><p><strong>Monica Geller:</strong> Well there&#39;s not much we can do.</p><blockquote><p>嗯，我们无能为力。</p></blockquote><p><strong>Rachel Green:</strong> (Like a big baby) Um... unless, unless I use yours.</p><blockquote><p>（像个大婴儿）嗯……除非，除非我用你的。</p></blockquote><p><strong>Monica Geller:</strong> Hah, no no no no no no no no no no.</p><blockquote><p>哈，不不不不。</p></blockquote><p><strong>Rachel Green:</strong> (Tapping the clipboard) well, now, wait a second, who did I just put as my &quot;In case of emergency&quot; person?</p><blockquote><p>（轻敲剪贴板）好吧，现在，等一下，我刚才把谁当成我的“紧急情况”人员了？</p></blockquote><p><strong>Monica Geller:</strong> (Looking around to check that no-one&#39;s listening, then lowering her voice anyway) That&#39;s insurance fraud.</p><blockquote><p>（环顾四周，确认没人在听，然后压低声音）那是保险欺诈。</p></blockquote><p><strong>Rachel Green:</strong> Well, alright, then, forget it. (Getting up to go) Might as well just go home. Ow ow ow ow!</p><blockquote><p>好吧，那么，算了吧。（起床要走）还是回家吧。哎哟！</p></blockquote><p><strong>Monica Geller:</strong> (Jumping up to make Rachel sit down) Okay, okay. I hate this.</p><blockquote><p>（跳起来让瑞秋坐下）好的，好的。我讨厌这个。</p></blockquote><p><strong>Rachel Green:</strong> Thank you. Thank you. I love you.</p><blockquote><p>谢谢你。非常感谢。我爱你。</p></blockquote><p><strong>Monica Geller:</strong> (to the nurse) Hi, (tiny laugh) um, I&#39;m gonna need a new set of (tiny laugh) these forms (tiny laugh).</p><blockquote><p>（对护士）嗨，（微笑）嗯，我需要一套新的（微笑）这些表格（微笑）。</p></blockquote><p><strong>Nurse:</strong> Why?</p><blockquote><p>为什么？</p></blockquote><p><strong>Monica Geller:</strong> (Tiny laugh) I am really an idiot. (Tiny laugh) you see, I was filling out my friend&#39;s form, and instead of putting her information, (tiny laugh) I put mine.</p><blockquote><p>（微微一笑）我真是个白痴。（微微一笑）你看，我在填写我朋友的表格，而不是把她的信息，（微微一笑）我把我的。</p></blockquote><p><strong>Nurse:</strong> You are an idiot. (She hands over a blank form).</p><blockquote><p>你是个白痴。（她交了一张空白表格）。</p></blockquote><p><strong>Monica Geller:</strong> (Tiny laugh) yep, that&#39;s me, (tiny laugh) I am that stupid (tiny laugh).</p><blockquote><p>（微微一笑）是的，就是我，（微微一笑）我就是那个傻瓜（微微一笑）。</p></blockquote><hr><p>🎬 <em>Central Perk, Chandler, has split up his newspaper so Joey can look at the funnies, while Ross&#39;s inappropriate joke at Lamaze class has come back to haunt him.</em></p><blockquote><p>🎬 <em>中央公园，钱德勒，把他的报纸拆开，让乔伊看笑话，而罗斯在拉玛兹课堂上不恰当的笑话又再次困扰着他。</em></p></blockquote><p><strong>Ross Geller:</strong> I had a dream last night where I was playing football with my kid.</p><blockquote><p>我昨晚做了个梦，梦见我和我的孩子一起踢足球。</p></blockquote><p>Chandler and **Joey Tribbiani: **That&#39;s nice.</p><blockquote><p>钱德勒和<strong>乔伊·崔比安尼：</strong>太好了。</p></blockquote><p><strong>Ross Geller:</strong> No, no, with him. (He mimes holding the baby like a football.) I&#39;m on this field, and they, they hike me the baby... and I, I know I&#39;ve gotta do something &#39;cause the Tampa Bay defence is comin&#39; right at me.</p><blockquote><p>不，不，和他在一起。（他模仿抱着孩子像足球一样。）我在这个场地上，他们，他们把孩子带到我身边……而我，我知道我必须做点什么，因为坦帕湾的防线正朝我走来。</p></blockquote><p><strong>Joey Tribbiani:</strong> Tampa Bay&#39;s got a terrible team.</p><blockquote><p>坦帕湾有一支很糟糕的球队。</p></blockquote><p><strong>Ross Geller:</strong> Right, but, it is just me and the baby, so I&#39;m thinkin&#39; they can take us. And so I uh, hah-hah, I just heave it down field.</p><blockquote><p>对，但是，只有我和孩子，所以我想他们可以带走我们。所以我呃，哈哈，我只是把它扔到地上。</p></blockquote><p><strong>Chandler Bing:</strong> What are you crazy? That&#39;s a baby!</p><blockquote><p>你疯了什么？那是个婴儿！</p></blockquote><p><strong>Joey Tribbiani:</strong> He should take the sack?</p><blockquote><p>他应该被解雇？</p></blockquote><p><strong>Ross Geller:</strong> Anyway, suddenly I&#39;m down field, and I realise that I&#39;m the one who&#39;s supposed to catch him, right? Only I know there is no way I&#39;m gonna get there in time, so I am running, and running, and that, that is when I woke up. See I, I am so not ready to be a father.</p><blockquote><p>不管怎样，突然间我来到了球场，我意识到我是应该抓住他的人，对吗？只有我知道我不可能及时赶到那里，所以我在跑步，跑步，那就是我醒来的时候。我知道，我还没准备好做父亲。</p></blockquote><p><strong>Chandler Bing:</strong> Hey, you&#39;re gonna be fine. You&#39;re one of the most caring, most responsible men in North America. You&#39;re gonna make a great dad.</p><blockquote><p>嘿，你会没事的。你是北美最有爱心、最负责任的人之一。你会成为一个好爸爸的。</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah, Ross. You and the baby just need better blocking.</p><blockquote><p>是的，罗斯。你和孩子只需要更好的阻隔。</p></blockquote><p><em>(Feeling a little better, Ross fetches more coffee.)</em></p><blockquote><p><em>（感觉好一点了，罗斯又拿了些咖啡。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Oh, have either one of you guys ever been to the Rainbow Room? Is it real expensive?</p><blockquote><p>哦，你们有谁去过彩虹屋吗？真的很贵吗？</p></blockquote><p><strong>Chandler Bing:</strong> Well, only if you order stuff.</p><blockquote><p>嗯，除非你点东西。</p></blockquote><p><strong>Joey Tribbiani:</strong> I&#39;m takin&#39; Ursula tonight. It&#39;s her birthday.</p><blockquote><p>我今晚要带乌苏拉。今天是她的生日。</p></blockquote><p><strong>Ross Geller:</strong> Wo-wo-whoa. What about Phoebe&#39;s birthday?</p><blockquote><p>哇哇。菲比的生日呢？</p></blockquote><p><strong>Joey Tribbiani:</strong> When&#39;s that?</p><blockquote><p>什么时候？</p></blockquote><p><strong>Ross Geller:</strong> Tonight.</p><blockquote><p>今晚。</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh, man. What&#39;re the odds of that happening?</p><blockquote><p>哦，伙计。发生这种情况的几率有多大？</p></blockquote><p><em>(Joey begins to contemplate his ill fortune.)</em></p><blockquote><p><em>（乔伊开始考虑他的厄运。）</em></p></blockquote><p><strong>Ross Geller:</strong> You take your time.</p><blockquote><p>你慢慢来。</p></blockquote><p><em>(Joey looks at his friends, thinks a bit more, then realises.)</em></p><blockquote><p><em>（乔伊看着他的朋友，多想了想，然后意识到。）</em></p></blockquote><p><strong>Chandler Bing:</strong> There it is! So what&#39;re you gonna do?</p><blockquote><p>在那里！那你打算怎么办？</p></blockquote><p><strong>Joey Tribbiani:</strong> What can I do? Look, I don&#39;t want to do anything to screw it up with Ursula.</p><blockquote><p>我能做什么？听着，我不想做任何事把乌苏拉搞砸。</p></blockquote><p><strong>Chandler Bing:</strong> And your friend Phoebe?</p><blockquote><p>那你的朋友菲比呢？</p></blockquote><p><strong>Joey Tribbiani:</strong> Well, if she&#39;s my friend, hopefully she&#39;ll understand. I mean, wouldn&#39;t you guys?</p><blockquote><p>如果她是我的朋友，希望她能理解。我是说，你们不是吗？</p></blockquote><p><strong>Chandler Bing:</strong> Man, if you tried something like that on my birthday, you&#39;d be starin&#39; at the business end of a hissy fit.</p><blockquote><p>老兄，如果你在我生日那天尝试这样的事情，你会在事业的最后开始发嘘声。</p></blockquote><p><em>(Joey gestures to show that he wouldn&#39;t dare...)</em></p><blockquote><p><em>（乔伊做手势表示他不敢…）</em></p></blockquote><hr><p>🎬 <em>The Hospital, Monica and Rachel are waiting for the doctors to arrive. They enter and are played by Noah Wyle and George Clooney.</em></p><blockquote><p>🎬 <em>医院，莫妮卡和瑞秋正在等待医生的到来。他们走进来，由诺亚·怀尔和乔治·克鲁尼扮演。</em></p></blockquote><p>Dr. Mitchell: ..you add a pinch of saffron, it makes all the difference.</p><blockquote><p>……你加一撮藏红花，就完全不同了。</p></blockquote><p><em>(They approach the young ladies. Dr. Mitchell consults Ms.Geller&#39;s admissions form.)</em></p><blockquote><p><em>（他们走近年轻女士。米切尔博士查阅了盖勒女士的入学表格。）</em></p></blockquote><p>Dr. Mitchell: Okay, errrr, Monica?</p><blockquote><p>好吧，呃，莫妮卡？</p></blockquote><p><strong>Monica Geller:</strong> Yes? (jumping as Rachel punches her arm) ..yes, she is.</p><blockquote><p>是吗？（瑞秋猛击手臂时跳了起来）……是的，她是。</p></blockquote><p>Rachel (as Monica): Hi, this is my friend Rachel.</p><blockquote><p>瑞秋（扮演莫妮卡）：嗨，这是我的朋友瑞秋。</p></blockquote><p>Monica (as Rachel): Hi.</p><blockquote><p>莫妮卡（扮演瑞秋）：嗨。</p></blockquote><p>Dr. Mitchell: (Smiling) Hi, err Rachel. I&#39;m Dr.Mitchell.</p><blockquote><p>（微笑）嗨，呃，瑞秋。我是米切尔博士。</p></blockquote><p>Dr. Rosen: (Smiling even more and attempting to take over) And I&#39;m his friend, Dr.Rosen.</p><blockquote><p>（笑得更厉害，试图接管）我是他的朋友，罗森医生。</p></blockquote><p><em>(Monica and Rachel smile back prettily.)</em></p><blockquote><p><em>（莫妮卡和瑞秋漂亮地笑了笑。）</em></p></blockquote><p><strong>Rachel Green:</strong> Aren&#39;t you a little cute to be a doctor?</p><blockquote><p>你当医生不是有点可爱吗？</p></blockquote><p>Dr. Rosen: Excuse me?</p><blockquote><p>对不起？</p></blockquote><p><strong>Rachel Green:</strong> I meant er, (struggling to concentrate) young, young, I meant young, young to be a doctor. Oh good, Rach.</p><blockquote><p>我的意思是，呃，（努力集中注意力）年轻，年轻，我的意思是年轻，当医生很年轻。哦，很好，瑞秋。</p></blockquote><p>Monica (as Rachel): Thank you.</p><blockquote><p>莫妮卡（扮演瑞秋）：谢谢你。</p></blockquote><p>Rachel (as Monica): Right.</p><blockquote><p>瑞秋（扮演莫妮卡）：对。</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, everyone but Joey is waiting for Phoebe to arrive for her surprise birthday party. Rachel and Monica is telling Chandler about Rachel&#39;s incident.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，除了乔伊，其他人都在等菲比来参加她的惊喜生日派对。瑞秋和莫妮卡正在告诉钱德勒瑞秋的事。</em></p></blockquote><p><strong>Rachel Green:</strong> ..so, he said it was just a sprain, and that was it.</p><blockquote><p>……所以，他说只是扭伤，就是这样。</p></blockquote><p><strong>Monica Geller:</strong> Uh, you left out the stupid part.</p><blockquote><p>嗯，你漏掉了愚蠢的部分。</p></blockquote><p><strong>Rachel Green:</strong> Not stupid. The very cute, cute, cute doctors asked us out for tomorrow night, and I said &quot;yes.&quot;</p><blockquote><p>不傻。非常可爱，可爱，可爱的医生邀请我们明天晚上出去，我说“是的。”</p></blockquote><p><strong>Monica Geller:</strong> I think it&#39;s totally insane, I mean, they work for the hospital. It&#39;s like returning to the scene of the crime. You know, I say we blow off the dates.</p><blockquote><p>我觉得这太疯狂了，我是说，他们在医院工作。就像回到犯罪现场一样。你知道，我说我们应该取消约会。</p></blockquote><p><strong>Rachel Green:</strong> What? Monica, they are cute, they are doctors, (spelling it out in the air for her slow friend) cute doctors, doctors who are cute!</p><blockquote><p>什么？莫妮卡，他们很可爱，他们是医生，（在空中为她的慢朋友拼出来）可爱的医生，可爱的医生！</p></blockquote><p><strong>Chandler Bing:</strong> Alright, what have we learned so far?</p><blockquote><p>好吧，到目前为止我们学到了什么？</p></blockquote><p><em>(There is a knock at the door. Someone turns the music off, then the whole party runs and hides, except for Monica and Rachel who answer their door. Ross stands in the doorway, holding a box, but everyone is too keyed up to notice that it&#39;s him.)</em></p><blockquote><p><em>（有人敲门。有人关掉了音乐，然后整个队伍都跑开躲藏起来，只有莫妮卡和瑞秋去开门。罗斯站在门口，手里拿着一个盒子，但每个人都兴奋得没注意到是他。）</em></p></blockquote><p><strong>The Whole Party:</strong> (Jumping up) SURPRISE!!!</p><blockquote><p>（跳起来）惊喜！！！</p></blockquote><p><em>(Ross is so startled that he throws his arms up to defend himself. The box takes off, then lands with a squishy thud, its contents oozing out onto the floor. Ross is not pleased.)</em></p><blockquote><p><em>（罗斯大吃一惊，他举起双臂自卫。箱子起飞，然后砰地一声落地，里面的东西都渗到了地板上。罗斯不高兴。）</em></p></blockquote><p><strong>Ross Geller:</strong> What the hell are you doing? You scared the crap outta me.</p><blockquote><p>你到底在干什么？你吓死我了。</p></blockquote><p><strong>Rachel Green:</strong> Was that the cake?</p><blockquote><p>那是蛋糕吗？</p></blockquote><p><strong>Ross Geller:</strong> Yeah, yeah. I got a lemon schmush.</p><blockquote><p>是的，是的。我有一个柠檬泥。</p></blockquote><p><strong>Monica Geller:</strong> Come on, she&#39;ll be here any minute.</p><blockquote><p>来吧，她随时都会来。</p></blockquote><p><em>(The whole party gathers round as Ross puts the box on the coffee table.)</em></p><blockquote><p><em>（当罗斯把盒子放在咖啡桌上时，整个队伍都围了过来。）</em></p></blockquote><p><strong>Rachel Green:</strong> I hope it&#39;s okay.</p><blockquote><p>我希望没事。</p></blockquote><p><em>(As Ross opens the lid, everybody looks at the mess inside.)</em></p><blockquote><p><em>（罗斯打开盖子时，每个人都看着里面乱七八糟的东西。）</em></p></blockquote><p><strong>Monica Geller:</strong> Oh...</p><blockquote><p>哦……</p></blockquote><p><strong>Chandler Bing:</strong> (Reading) &quot;Happy Birthday Peehe.&quot;</p><blockquote><p>（读着）“生日快乐，皮耶。”</p></blockquote><p><strong>Monica Geller:</strong> Well maybe we can make a, a, a &#39;B&#39; out of one of those roses.</p><blockquote><p>也许我们可以用其中一朵玫瑰做一个，一个，一个。</p></blockquote><p><em>(Phoebe quietly wanders in, to join the tableau.)</em></p><blockquote><p><em>（菲比静静地走了进来，加入到画面中。）</em></p></blockquote><p><strong>Ross Geller:</strong> (Still annoyed) Yeah, we&#39;ll just use our special cake tools.</p><blockquote><p>（仍然很生气）是的，我们就用我们的蛋糕专用工具吧。</p></blockquote><p><strong>Phoebe Buffay:</strong> Hey, what&#39;s going on?</p><blockquote><p>嘿，发生什么事了？</p></blockquote><p><strong>Ross Geller:</strong> Oh, we just...</p><blockquote><p>哦，我们只是……</p></blockquote><p>Phoebe&#39;s Friends: (Finally noticing the guest of honour) Surprise!</p><blockquote><p>（终于注意到主宾）惊喜！</p></blockquote><p><strong>Phoebe Buffay:</strong> (Delighted) oh, oh, oh! This is so great! Oh my god! This was not at all scary. Hi everybody. Hi Betty! Betty, Hi! (Thrilled) You found Betty! Oh my god! (Hugging people) This is great. Everybody I love is in the same room, (still happy) Where&#39;s Joey?</p><blockquote><p>（高兴地）哦，哦，哦！这太棒了！哦，我的上帝！这一点也不可怕。大家好。嗨，贝蒂！贝蒂，你好！（激动）你找到贝蒂了！哦，我的上帝！（拥抱人们）这太棒了。我爱的每个人都在同一个房间里，（仍然很高兴）乔伊在哪里？</p></blockquote><p><em>(The party falls flat. Chandler tries to think of a witticism, but even he can&#39;t help...)</em></p><blockquote><p><em>（聚会失败了。钱德勒试图想出一个妙语，但他也忍不住……）</em></p></blockquote><p><strong>Chandler Bing:</strong> Did you see Betty?</p><blockquote><p>你看见贝蒂了吗？</p></blockquote><p><em>(Betty waggles her fingers to say &quot;Hi&quot;, but Phoebe feels her birthday has been ruined by her twin.)</em></p><blockquote><p><em>（贝蒂摇着手指说“嗨”，但菲比觉得她的生日被她的双胞胎兄弟给毁了。）</em></p></blockquote><hr><p>🎬 <em>A Restaurant, Ross is having lunch with his father who is examining his next forkful.</em></p><blockquote><p>🎬 <em>一家餐馆，罗斯正在和他的父亲共进午餐，他父亲正在检查他的下一个餐叉。</em></p></blockquote><p>Mr. Geller: I tell you one thing, I wouldn&#39;t mind having a piece of this sun-dried tomato business. Five years ago, if somebody had said to me, here&#39;s a tomato that looks like a prune, I&#39;d say &quot;get out of my office!&quot;</p><blockquote><p>我告诉你一件事，我不介意在这个晒干番茄生意中分一杯羹。五年前，如果有人对我说，这是一个看起来像李子的西红柿，我会说“滚出我的办公室！”</p></blockquote><p><strong>Ross Geller:</strong> Dad, before I was born, did you freak out at all?</p><blockquote><p>爸爸，在我出生之前，你有没有疯过？</p></blockquote><p>Mr. Geller: I&#39;m not freaking out, I&#39;m just saying, if somebody had come to me with the idea andndash;</p><blockquote><p>我不是吓坏了，我只是说，如果有人带着这个想法来找我，安德达斯；</p></blockquote><p><strong>Ross Geller:</strong> Dad, dad, dad, I&#39;m talkin&#39; about the whole uh, baby thing. Did you uh, ever get this sort of... panicky, &quot;Oh my god I&#39;m gonna be a father&quot; kind of a thing?</p><blockquote><p>爸爸，爸爸，爸爸，我说的是整个呃，宝贝的事情。你有没有得到过这种……惊慌失措，“天哪，我要当爸爸了”之类的话？</p></blockquote><p>Mr. Geller: No. Your mother really did the work. I was busy with the business. I wasn&#39;t around that much. Is that what this is about?</p><blockquote><p>不，是你妈妈干的。我忙着做生意。我不常在附近。这就是为什么？</p></blockquote><p><strong>Ross Geller:</strong> No, no, Dad, I was just wondering.</p><blockquote><p>不，不，爸爸，我只是想知道。</p></blockquote><p>Mr. Geller: &#39;Cause there&#39;s time to make up for that. We can do stuff together. You always wanted to go to that Colonial Williamsburg. How &#39;bout we do that?</p><blockquote><p>因为有时间来弥补这一点。我们可以一起做事。你一直想去威廉斯堡殖民地。我们那样做怎么样？</p></blockquote><p><strong>Ross Geller:</strong> Thanks, Dad, really, I ju... you know, I just, I just needed to know, um... when did you start to feel like a father?</p><blockquote><p>谢谢，爸爸，真的，我……你知道，我只是，我只是想知道，嗯……你什么时候开始觉得自己像个父亲？</p></blockquote><p>Mr. Geller: Oh, well, I, I guess it musta been the day after you were born. We were in the hospital room, your mother was asleep, and they brought you in and gave you to me. You were this ugly little red thing, and all of a sudden you grabbed my finger with your whole fist. And you squeezed it, so tight. And that&#39;s when I knew.</p><blockquote><p>哦，好吧，我，我想那一定是你出生的第二天。我们在病房里，你妈妈睡着了，他们把你带进来，把你交给了我。你是个丑陋的红色小东西，突然你用整个拳头抓住了我的手指。你把它挤得太紧了。就在那时我知道了。</p></blockquote><p><em>(Ross is so moved by his father&#39;s charming story, that he stops eating.)</em></p><blockquote><p><em>（罗斯被他父亲的迷人故事深深打动了，他停止了吃饭。）</em></p></blockquote><p>Mr. Geller: So you don&#39;t wanna go to Williamsburg?</p><blockquote><p>所以你不想去威廉斯堡？</p></blockquote><p><strong>Ross Geller:</strong> No, we can go to Williamsburg.</p><blockquote><p>不，我们可以去威廉斯堡。</p></blockquote><p>Mr. Geller: Eat your fish.</p><blockquote><p>吃你的鱼。</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Monica is just getting off of the intercom and turns off the TV which is still in the SAP mode.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，莫妮卡刚从对讲机上下来，关掉仍处于SAP模式的电视。</em></p></blockquote><p><strong>Monica Geller:</strong> Rachel, the cute doctors are here.</p><blockquote><p>瑞秋，可爱的医生来了。</p></blockquote><p><strong>Rachel Green:</strong> (entering from her room) Okay, coming!</p><blockquote><p>（从她的房间进来）好的，来了！</p></blockquote><p><em>(Monica opens the door for Dr. Mitchell and Dr. Geoffrey.)</em></p><blockquote><p><em>（莫妮卡为米切尔博士和杰弗里博士开门。）</em></p></blockquote><p><strong>Monica Geller:</strong> Hi, come on in.</p><blockquote><p>嗨，进来吧。</p></blockquote><p>Dr. Mitchell: Hey.</p><blockquote><p>嘿。</p></blockquote><p><strong>Monica Geller:</strong> Hi, Geoffrey.</p><blockquote><p>嗨，杰弗里。</p></blockquote><p><strong>Rachel Green:</strong> Hi.</p><blockquote><p>嗨。</p></blockquote><p>Dr. Rosen: Ah here, we brought wine.</p><blockquote><p>啊，我们带来了葡萄酒。</p></blockquote><p>Dr. Mitchell: Look at this, it&#39;s from the cellars of Ernest and Tova Borgnine, so how could we resist?</p><blockquote><p>看看这个，是从欧内斯特和托瓦·博格宁的地窖里拿来的，我们怎么能抗拒呢？</p></blockquote><p><strong>Rachel Green:</strong> Oh, that&#39;s great. Look at that.</p><blockquote><p>哦，太好了。看那个。</p></blockquote><p>Dr. Rosen: So, Monica, how&#39;s the ankle?</p><blockquote><p>莫妮卡，脚踝怎么样？</p></blockquote><p><strong>Monica Geller:</strong> It&#39;s uh...</p><blockquote><p>嗯……</p></blockquote><p><em>(Rachel discreetly coughs to warn her.)</em></p><blockquote><p><em>（瑞秋小心翼翼地咳嗽警告她。）</em></p></blockquote><p>Monica (as Rachel): ..well, why don&#39;t you tell them? After all it, is your ankle.</p><blockquote><p>莫妮卡（扮演瑞秋）：……嗯，你为什么不告诉他们？毕竟是你的脚踝。</p></blockquote><p>Rachel (as Monica): You know what, it&#39;s feeling a lot better, thank you, um... Well, listen, why don&#39;t you two sit down and, and we&#39;ll get you some glasses... okay... (They don&#39;t know what to do with their coats and Monica points to the living room) STAT!</p><blockquote><p>瑞秋（扮演莫妮卡）：你知道吗，感觉好多了，谢谢你，嗯……好吧，听着，你们俩为什么不坐下来，我们给你们拿些玻璃杯……可以（他们不知道如何处理他们的外套，莫妮卡指着客厅）统计！</p></blockquote><p><em>(Rachel joins Monica who is in the kitchen area, opening the wine bottle. Rachel checks that the doctors aren&#39;t listening, then lowers her voice anyway.)</em></p><blockquote><p><em>（瑞秋和莫妮卡一起来到厨房，打开酒瓶。瑞秋检查医生是否在听，然后还是压低了声音。）</em></p></blockquote><p><strong>Rachel Green:</strong> Okay, listen, I&#39;m thinking, why don&#39;t we just tell them who we really are? I mean, it&#39;ll be fine, I really think it&#39;ll be fine.</p><blockquote><p>好吧，听着，我在想，我们为什么不告诉他们我们到底是谁？我是说，会好的，我真的认为会好的。</p></blockquote><p><strong>Monica Geller:</strong> It will not be fine. We&#39;ll get in trouble.</p><blockquote><p>不会好的。我们会有麻烦的。</p></blockquote><p><strong>Rachel Green:</strong> Oh, Monica! Would you stop being such a wuss?</p><blockquote><p>哦，莫妮卡！你能不能别再这样无能了？</p></blockquote><p><strong>Monica Geller:</strong> A wuss? Excuse me for living in the real world, okay?</p><blockquote><p>胆小鬼？原谅我生活在现实世界里，好吗？</p></blockquote><p><em>(Back at the couch, Dr. Mitchell and Dr. Rosen have concerns of their own.)</em></p><blockquote><p><em>（回到沙发上，米切尔博士和罗森博士也有自己的担忧。）</em></p></blockquote><p>Dr. Mitchell: So?</p><blockquote><p>那么？</p></blockquote><p>Dr. Rosen: So... they sss-still seem normal.</p><blockquote><p>那么……它们看起来仍然很正常。</p></blockquote><p>Dr. Mitchell: That&#39;s because they are.</p><blockquote><p>那是因为他们是。</p></blockquote><p>Dr. Rosen: (Nervously) okay, but you have to admit that every time we go out... Women we meet at the hospital... It turns into...</p><blockquote><p>（紧张地）好吧，但你必须承认每次我们出去……我们在医院遇到的女人……它变成了……</p></blockquote><p>Dr. Mitchell: Willya relax? Look around. No pagan altars, no piles of bones in the corners, they&#39;re fine. (Baring his teeth to clean them with his finger) Go like this. (Dr. Rosen obeys.)</p><blockquote><p>放松点好吗？看看周围。没有异教祭坛，角落里没有成堆的骨头，它们很好。（露出牙齿用手指清洁）像这样走。（罗森博士服从了。）</p></blockquote><p><em>(Meanwhile, back at the sink.)</em></p><blockquote><p><em>（与此同时，回到水槽。）</em></p></blockquote><p><strong>Monica Geller:</strong> I said we are not going to do it, okay? Sometimes you can be such a, a big baby.</p><blockquote><p>我说过我们不会这么做的，好吗？有时候你会变成一个大孩子。</p></blockquote><p><strong>Rachel Green:</strong> (Resenting the truth) I am not a baby! You know what? I swear to god, just because you get so uptight every time we...</p><blockquote><p>（对事实不满）我不是婴儿！你知道吗？我向上帝发誓，只是因为每次我们……</p></blockquote><p><strong>Monica Geller:</strong> Sure, every time, you&#39;re such a princess...</p><blockquote><p>当然，每一次，你都是这样的公主……</p></blockquote><p><strong>Rachel Green:</strong> You know what?</p><blockquote><p>你知道吗？</p></blockquote><p><strong>Monica Geller:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Rachel Green:</strong> You know what?</p><blockquote><p>你知道吗？</p></blockquote><p><strong>Monica Geller:</strong> What!?</p><blockquote><p>什么！？</p></blockquote><p><strong>Rachel Green:</strong> You know what?</p><blockquote><p>你知道吗？</p></blockquote><p><strong>Monica Geller:</strong> (getting angry) What!!?</p><blockquote><p>（生气）什么！！？</p></blockquote><p><strong>Rachel Green:</strong> Every day, you are becoming more and more like your mother.</p><blockquote><p>每天，你都越来越像你妈妈了。</p></blockquote><p><em>(Rachel brightly limps back across the apartment with glasses of wine for the cute doctors, leaving an open-mouthed Monica in her wake.)</em></p><blockquote><p><em>（瑞秋带着为可爱的医生们准备的酒杯，一瘸一拐地穿过公寓，留下一个张着嘴的莫妮卡。）</em></p></blockquote><p><strong>Rachel Green:</strong> Hello! Here we go!</p><blockquote><p>你好！我们走！</p></blockquote><p>Dr. Rosen: This is a great place. How long have you lived here?</p><blockquote><p>这是个好地方。你在这里住了多久了？</p></blockquote><p><strong>Rachel Green:</strong> (as Monica) Thanks! I&#39;ve been here about six years, and Rachel moved in a few months ago.</p><blockquote><p>（作为莫妮卡）谢谢！我在这里已经六年了，瑞秋几个月前搬了进来。</p></blockquote><p><strong>Monica Geller:</strong> (as Rachel) Yeah... (joining the others) ..see, I was supposed to get married, but, um, I left the guy at the altar.</p><blockquote><p>（扮演瑞秋）是的……（加入其他人）…看，我本来应该结婚的，但是，嗯，我把那个家伙留在祭坛上了。</p></blockquote><p><em>(Rachel tries to hide her alarm, but she squirms in her chair.)</em></p><blockquote><p><em>（瑞秋试图隐藏她的警报，但她在椅子上扭动。）</em></p></blockquote><p>Dr. Mitchell: Really?</p><blockquote><p>真的吗？</p></blockquote><p><strong>Monica Geller:</strong> (as Rachel) Yeah... Yeah, I know it&#39;s pretty selfish, but haha, hey, that&#39;s me. (Indicating a dish on the table) Why don&#39;t you try the hummus?</p><blockquote><p>（扮演瑞秋）是的……是的，我知道这很自私，但是哈哈，嘿，是我。（指着桌上的一道菜）你为什么不试试鹰嘴豆泥呢？</p></blockquote><p>Dr. Rosen: So, Monica, what do you do?</p><blockquote><p>莫妮卡，你是做什么的？</p></blockquote><p><strong>Rachel Green:</strong> (as Monica) Aahh, I&#39;m a... chef at a restaurant uptown.</p><blockquote><p>（扮演莫妮卡）啊，我是……住宅区一家餐馆的厨师。</p></blockquote><p>Dr. Rosen: Good for you.</p><blockquote><p>对你有好处。</p></blockquote><p><strong>Rachel Green:</strong> (as Monica) Yeah it is, mostly because I get to boss people around, which I just love to do.</p><blockquote><p>（扮演莫妮卡）是的，主要是因为我能领导周围的人，我就是喜欢这样。</p></blockquote><p>Dr. Rosen: This hummus is great.</p><blockquote><p>这个鹰嘴豆泥很棒。</p></blockquote><p>Dr. Mitchell: God bless the chickpea.</p><blockquote><p>上帝保佑鹰嘴豆。</p></blockquote><p><strong>Monica Geller:</strong> (as Rachel) (Suddenly laughing) Oh, god, I am so spoiled... That&#39;s it!</p><blockquote><p>（扮演瑞秋）（突然大笑）哦，天哪，我被宠坏了……就这样！</p></blockquote><p><em>(The doctors don&#39;t know what to make of all this.)</em></p><blockquote><p><em>（医生们不知道如何看待这一切。）</em></p></blockquote><p><strong>Rachel Green:</strong> (as Monica) And by the way, have I mentioned that back in high school, I was a cow?</p><blockquote><p>（作为莫妮卡）顺便问一下，我在高中时提到过，我是一头母牛吗？</p></blockquote><p><strong>Monica Geller:</strong> (as Rachel) I used to wet my bed.</p><blockquote><p>（扮演瑞秋）我过去常尿床。</p></blockquote><p><strong>Rachel Green:</strong> (as Monica) I use my breasts to get other people&#39;s attention.</p><blockquote><p>（扮演莫妮卡）我用我的乳房来吸引别人的注意。</p></blockquote><p><strong>Monica Geller:</strong> (as Rachel) (Revealing her anger to point at her best friend) We both do that!</p><blockquote><p>（扮演瑞秋）（露出愤怒指向她最好的朋友）我们都这么做！</p></blockquote><p><em>(Rachel lets her anger show too. Hideously embarrassed, the doctors drain their glasses in the vicious pause which follows. The telephone rings, but the girls just glower at each other, silently daring the other to move first. Finally both guys jump up, and Michael wins.)</em></p><blockquote><p><em>（瑞秋也表现出了愤怒。医生们尴尬得要命，在接下来的恶毒停顿中倒掉了眼镜。电话铃响了，但女孩们只是互相怒视，默默地鼓励对方先走一步。最后两个男孩都跳了起来，迈克尔赢了。）</em></p></blockquote><p>Dr. Mitchell: (on the phone) Monica and Rachel&#39;s apartment. Err yeh, aayah, yeh, just one second... (handing it to Monica) ..ah, Rachel, it&#39;s your dad.</p><blockquote><p>（在电话里）莫妮卡和瑞秋的公寓。呃，耶，啊，耶，就一秒钟……（递给莫妮卡）…啊，瑞秋，是你爸爸。</p></blockquote><p><strong>Monica Geller:</strong> (as Rachel) Hi, Dad. No, no, it&#39;s me. (Getting up to move further away from Rachel) li-listen, Dad, I can&#39;t talk right now, um, but there&#39;s something, um... there&#39;s something that I&#39;ve been meaning to tell you...</p><blockquote><p>（扮演瑞秋）嗨，爸爸。不，不，是我。（站起来离瑞秋远一点）听着，爸爸，我现在不能说话，嗯，但是有件事，嗯……有件事我一直想告诉你……</p></blockquote><p><em>(Monica glares triumphantly across the room, scaring Rachel who also stands up.)</em></p><blockquote><p><em>（莫妮卡得意洋洋地瞪着房间的另一边，吓坏了瑞秋，瑞秋也站了起来。）</em></p></blockquote><p><strong>Rachel Green:</strong> Would you excuse me for a second?</p><blockquote><p>请原谅我一会儿好吗？</p></blockquote><p><strong>Monica Geller:</strong> (as Rachel) Remember back in freshman year? (Talking fast before Rachel can catch her) Well, Billy Dreskin and I had sex on your bed.</p><blockquote><p>（作为瑞秋）还记得大一的时候吗？（瑞秋还没来得及抓住她，就说得很快）好吧，比利·德雷斯金和我在你床上做爱了。</p></blockquote><p><em>(Completely undone by Monica&#39;s verbal destruction, Rachel almost loses her balance as she staggers backwards, eyes agog, gasping for breath, and literally not knowing which way to turn. Finally, she escapes into the bathroom while a resigned Dr. Mitchell looks philosophically at Dr. Rosen who seems about remind him of the good old days at the pagan altar.)</em></p><blockquote><p><em>（被莫妮卡的语言破坏彻底摧毁，瑞秋几乎失去了平衡，她蹒跚后退，眼睛瞪得紧紧的，喘不过气来，简直不知道该怎么办。最后，她逃进了浴室，而辞职的米切尔医生哲理地看着罗森博士，罗森博士似乎让他想起了在帕加的美好时光（祭坛上）</em></p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, the next morning, Ross, Phoebe, Chandler and Monica sit round the coffee table, playing Scrabble. Rachel, still in her dressing gown, is pleading on the phone, her free hand shaking with agitation.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，第二天早上，罗斯、菲比、钱德勒和莫妮卡围坐在咖啡桌旁玩拼字游戏。瑞秋仍然穿着晨衣，正在打电话求情，她的自由手激动地颤抖着。</em></p></blockquote><p><strong>Rachel Green:</strong> (on phone) Daddy... Daddy... Daddy, why whyyy would I sleep with Billy Dreskin? His father tried to put you out of business! (Rachel turns to Monica, clasping the receiver to her bosom so Dr.Green can&#39;t hear, while mouthing &quot;You are...&quot;) ...dead!</p><blockquote><p>（在电话里）爸爸……爸爸……爸爸，我为什么要和比利·德雷斯金睡觉？他父亲想让你破产！（瑞秋转向莫妮卡，把听筒紧紧地抱在怀里，让格林医生听不见，同时嘴里说：“你是……”死了！</p></blockquote><p><em>(Monica smiles a sweet apology of regret, until she&#39;s distracted by Marcel as he clambers all over her nice furniture.)</em></p><blockquote><p><em>（莫妮卡微笑着表示遗憾的甜蜜道歉，直到她被马赛尔分心，因为他在她漂亮的家具上爬来爬去。）</em></p></blockquote><p><strong>Monica Geller:</strong> Ross, he&#39;s got the remote again.</p><blockquote><p>罗斯，他又拿到遥控器了。</p></blockquote><p><strong>Ross Geller:</strong> Good. Maybe he can switch it back.</p><blockquote><p>很好。也许他可以把它换回去。</p></blockquote><p><em>(Marcel changes channel to Bugs Bunny, who is speaking in Spanish.)</em></p><blockquote><p><em>（Marcel将频道切换为Bugs Bunny，他正在讲西班牙语。）</em></p></blockquote><p><strong>Ross Geller:</strong> Maybe not.</p><blockquote><p>也许不是。</p></blockquote><p><em>(Meanwhile, Rachel has taken another call, from a nurse she&#39;d hoped never to hear from again.)</em></p><blockquote><p><em>（与此同时，瑞秋又接到了一个护士打来的电话，她本来希望再也听不到她的电话。）</em></p></blockquote><p><strong>Rachel Green:</strong> Hello? (Listens) Um, yeah, uh, (snapping her fingers at Ross who takes the remote from Marcel, then turns off the TV) Okay ah, hold on a second, lemme lemme just check and see if see if she&#39;s here.</p><blockquote><p>喂？（听）嗯，是的，嗯，（对着从Marcel拿遥控器的Ross弹手指，然后关掉电视）好的，啊，等一下，lemme lemme，看看她是否在这里。</p></blockquote><p><em>(All animosity forgotten, Rachel holds the receiver out as she limps quickly over to her friend, who stands up in concern.)</em></p><blockquote><p><em>（所有的仇恨都被忘记了，瑞秋把听筒拿了出来，一瘸一拐地快速走向她的朋友，她担心地站了起来。）</em></p></blockquote><p><strong>Rachel Green:</strong> It&#39;s the woman from the hospital admissions office. She says there&#39;s a problem with the form. Oh, god, oh god...</p><blockquote><p>是住院部的那个女人。她说表格有问题。哦，天哪，哦，天哪……</p></blockquote><p>Rachel and **Monica Geller: **Oh god, waddawe do, waddawe do, waddawe do?</p><blockquote><p>瑞秋和<strong>莫妮卡·盖勒：</strong>哦，天哪，沃德道，沃德道，沃德道？</p></blockquote><p><strong>Monica Geller:</strong> I don&#39;t know! Why don&#39;t you just explain? What do they want? Find out what they want!</p><blockquote><p>我不知道！你为什么不解释一下？他们想要什么？找出他们想要什么！</p></blockquote><p><strong>Rachel Green:</strong> Okay (desperately hands the receiver over) no, you do it.</p><blockquote><p>好的（拼命地把听筒递过来）不，你来吧。</p></blockquote><p><strong>Monica Geller:</strong> (taking the phone) Hello, this is Monica... Yeah??? Oh... (Smiles at Rachel to reassure her) Okay, yes, we&#39;ll be right, we&#39;ll be right down.(Listens) Thank you. (Hangs up)</p><blockquote><p>（拿起电话）你好，我是莫妮卡……是 啊哦（微笑着向瑞秋保证）好的，是的，我们马上下来。（听）谢谢。（挂断电话）</p></blockquote><p><strong>Rachel Green:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Monica Geller:</strong> We forgot to sign one of the admissions forms.</p><blockquote><p>我们忘了在一张入学表格上签名。</p></blockquote><p><strong>Rachel Green:</strong> Ohhh... (slumping in relief) Okay, you were right. You were right! This was just not worth it.</p><blockquote><p>哦……（松了一口气）好吧，你说得对。你是对的！这不值得。</p></blockquote><p><strong>Monica Geller:</strong> Thank you.</p><blockquote><p>谢谢。</p></blockquote><p><strong>Rachel Green:</strong> Okay, let me just change.</p><blockquote><p>好吧，让我换衣服。</p></blockquote><p><strong>Monica Geller:</strong> Yes.</p><blockquote><p>是的。</p></blockquote><p><em>(Rachel goes to her room.)</em></p><blockquote><p><em>（瑞秋回到她的房间。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> (entering quietly) Hey.</p><blockquote><p>（悄悄地进来）嘿。</p></blockquote><p>Ross and **Chandler Bing: **Hey!</p><blockquote><p>罗斯和<strong>钱德勒·宾：</strong>嘿！</p></blockquote><p><strong>Monica Geller:</strong> Hi.</p><blockquote><p>嗨。</p></blockquote><p><strong>Phoebe Buffay:</strong> Trouble?</p><blockquote><p>麻烦？</p></blockquote><p><strong>Joey Tribbiani:</strong> Your sister stood me up the other night.</p><blockquote><p>你姐姐那天晚上放我鸽子了。</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, no. Don&#39;t you hate it when people aren&#39;t there for you?</p><blockquote><p>哦，不。当人们不在你身边时，你不讨厌吗？</p></blockquote><p><strong>Ross Geller:</strong> Well did you try calling her?</p><blockquote><p>你试着给她打电话了吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> I&#39;ve been trying for two days. When I called the restaurant, they said she was too busy to talk. I can&#39;t believe she&#39;s blowin&#39; me off.</p><blockquote><p>我已经试了两天了。我给餐馆打电话时，他们说她太忙了，不能说话。我真不敢相信她竟然对我吹毛求疵。</p></blockquote><p><em>(Phoebe wants to be angry with Joey, but as she watches him shaking his head in pain and disbelief, she knows that it isn&#39;t his fault.)</em></p><blockquote><p><em>（菲比想生乔伊的气，但当她看着乔伊痛苦而难以置信地摇头时，她知道这不是他的错。）</em></p></blockquote><hr><p>🎬 <em>Riff&#39;s, Phoebe is entering. Ursula returns with two plates of chicken, but she only has time to set one on the table, when...</em></p><blockquote><p>🎬 <em>里夫家，菲比进来了。乌苏拉带着两盘鸡肉回来，但她只有时间把一盘放在桌子上，这时…</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Hey.</p><blockquote><p>嘿。</p></blockquote><p><em>(Ursula turns in surprise.)</em></p><blockquote><p><em>（乌苏拉惊讶地转过身来。）</em></p></blockquote><p><strong>Ursula:</strong> Oh!</p><blockquote><p>哦！</p></blockquote><p><strong>Phoebe Buffay:</strong> Um you, you got a minute?</p><blockquote><p>嗯，你，你有时间吗？</p></blockquote><p><strong>Ursula:</strong> Um, yeah, I&#39;m just... (waving dismissively at the concept) ..working.</p><blockquote><p>嗯，是的，我只是……（轻蔑地挥舞着这个概念）…工作。</p></blockquote><p><em>(Ursula points out a vacant table, so the twins walk over, side by side, to sit down. Departing customers walk right past the pair. Sitting at the back, a hungry gentleman looks most annoyed as Ursula sets his meal down in front of her. The girls sit.)</em></p><blockquote><p><em>（厄休拉指了指一张空桌子，于是这对双胞胎肩并肩走过来坐下。离开的顾客正好从这对双胞胎身边走过。坐在后面的一位饥饿的绅士看起来非常恼火，因为厄休拉把饭放在她面前。女孩们坐着。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> So.</p><blockquote><p>那么。</p></blockquote><p><strong>Ursula:</strong> Uh-huh.</p><blockquote><p>嗯。</p></blockquote><p><em>(Ursula is genuinely pleased that her sister has visited her, after so many years. Phoebe hesitates over how best to begin.)</em></p><blockquote><p><em>（多年后，乌苏拉真的很高兴姐姐来看望她。菲比犹豫了一下该如何开始。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Um, oh, I got you a birthday present.</p><blockquote><p>嗯，哦，我给你买了一份生日礼物。</p></blockquote><p><em>(Ursula picks up a fork and begins eating the meat, while Phoebe removes a present from her bag.)</em></p><blockquote><p><em>（乌苏拉拿起叉子开始吃肉，菲比从包里拿出礼物。）</em></p></blockquote><p><strong>Ursula:</strong> Oh, wow! You remembered! (Opening it) Oh! It&#39;s a Judy Jetson thermos!</p><blockquote><p>哦，哇！你记得！（打开）哦！这是朱迪·杰森热水瓶！</p></blockquote><p><em>(She laughs at the childhood memory. Phoebe smiles at being able to make her point.)</em></p><blockquote><p><em>（她笑了笑童年的记忆。菲比笑了笑，因为她能说出自己的观点。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Right, like the kind you...</p><blockquote><p>对，就像你……</p></blockquote><p><strong>Ursula:</strong> Right... Oh, I got something for you, too.</p><blockquote><p>对……哦，我也有东西给你。</p></blockquote><p><em>(Ursula gets up to fetch a box from her bag by the counter.)</em></p><blockquote><p><em>（厄秀拉站起来从柜台边的包里拿出一个盒子。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> How&#39;d you know I was coming?</p><blockquote><p>你怎么知道我要来？</p></blockquote><p><strong>Ursula:</strong> Um, yeah, um, twin thing.</p><blockquote><p>嗯，是的，嗯，双胞胎。</p></blockquote><p><em>(Ursula puts the box directly into Phoebe&#39;s hand. Phoebe brightens.)</em></p><blockquote><p><em>（厄苏拉把盒子直接放在菲比的手里。菲比变亮了。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> I can&#39;t believe you did this.</p><blockquote><p>我真不敢相信你会这么做。</p></blockquote><p><em>(Phoebe opens the box, to find something familiar inside.)</em></p><blockquote><p><em>（菲比打开盒子，发现里面有些熟悉的东西。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> I can&#39;t believe you... (holding up Joey&#39;s cardigan) ..did this.</p><blockquote><p>我真不敢相信你……（举着乔伊的羊毛衫）…是这样的。</p></blockquote><p><em>(Phoebe&#39;s smile hardens as she packs the cardigan away.)</em></p><blockquote><p><em>（菲比一边收起羊毛衫，一边微笑着。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> So... What&#39;s the deal with umm, you and Joey?</p><blockquote><p>那么……你和乔伊怎么了？</p></blockquote><p><strong>Ursula:</strong> Oh, right. He is so great. But that&#39;s over.</p><blockquote><p>哦，对了。他太棒了。但这一切都结束了。</p></blockquote><p><em>(Ursula resumes eating her lunch..)</em></p><blockquote><p><em>（乌苏拉继续吃她的午餐。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Does he know?</p><blockquote><p>他知道吗？</p></blockquote><p><strong>Ursula:</strong> Who?</p><blockquote><p>谁？</p></blockquote><p><strong>Phoebe Buffay:</strong> Joey. You know, um, he&#39;s really nutsy about you.</p><blockquote><p>乔伊。你知道，他真的很喜欢你。</p></blockquote><p><strong>Ursula:</strong> He is? Why?</p><blockquote><p>是吗？为什么？</p></blockquote><p><strong>Phoebe Buffay:</strong> You got me.</p><blockquote><p>你抓住我了。</p></blockquote><p><strong>Ursula:</strong> Right.</p><blockquote><p>对。</p></blockquote><p><em>(A waiter comes over for the stolen chicken. Ursula turns to him.)</em></p><blockquote><p><em>（一个服务员过来拿偷来的鸡。厄秀拉转向他。）</em></p></blockquote><p><strong>Ursula:</strong> Excuse me. Doesn&#39;t this come with a side salad?</p><blockquote><p>对不起。这不是附带沙拉吗？</p></blockquote><p><em>(The man gives up, shaking his head.)</em></p><blockquote><p><em>（男子摇了摇头，放弃了。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> So, um, are you gonna call him?</p><blockquote><p>那么，嗯，你要给他打电话吗？</p></blockquote><p><strong>Ursula:</strong> What? (Indicating the departing waiter) Do you think he likes me?</p><blockquote><p>什么？（指着即将离开的服务员）你认为他喜欢我吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> No, Joey.</p><blockquote><p>不，乔伊。</p></blockquote><p><strong>Ursula:</strong> Oh. No, no, he is so smart. He&#39;ll figure it out. (Offering to share her food) Do you want some chicken?</p><blockquote><p>哦。不，不，他太聪明了。他会找到答案的。（主动提出与她分享食物）你想要些鸡肉吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> No. No food with a face.</p><blockquote><p>不，没有带脸的食物。</p></blockquote><p><strong>Ursula:</strong> You have not changed!</p><blockquote><p>你没有变！</p></blockquote><p><em>(Ursula&#39;s eyes dance as she laughs and smiles, simply glad to be back with her sister.)</em></p><blockquote><p><em>（厄休拉笑着，眼睛里跳着舞，很高兴能和姐姐在一起。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah, you too.</p><blockquote><p>是啊，你也是。</p></blockquote><p><em>(Trying not to wrinkle her nose, Phoebe smiles back realising it&#39;s down to her to make up for her negligent sister. Meanwhile, Ursula still hasn&#39;t received her side salad, but when she attempts to attract the waiter&#39;s attention, he ignores her.)</em></p><blockquote><p><em>（菲比尽量不皱起鼻子，微笑着回应，意识到这要由她来弥补她疏忽大意的妹妹。与此同时，乌苏拉还没有收到她的配菜沙拉，但当她试图吸引服务员的注意时，他忽略了她。）</em></p></blockquote><hr><p>🎬 <em>The Emergency Room. The officious admissions nurse is again on duty. Rachel and Monica enter, looking worried. As they approach the desk, Rachel adopts a winning smile, while Monica struggles to smile at all.</em></p><blockquote><p>🎬 <em>急诊室。多管闲事的入院护士再次值班。瑞秋和莫妮卡进来，看起来很担心。当他们走近办公桌时，瑞秋露出了胜利的微笑，而莫妮卡则竭力保持微笑。</em></p></blockquote><p><strong>Rachel Green:</strong> (as Monica) Hi, remember us?</p><blockquote><p>（扮演莫妮卡）嗨，还记得我们吗？</p></blockquote><p><strong>Nurse:</strong> (Grimacing) Mmm hmmm.</p><blockquote><p>（做鬼脸）嗯哼。</p></blockquote><p><strong>Monica Geller:</strong> (as Rachel) Um, okay. You just called a little while ago about needing a signature on the admissions form. Well, it turns out we need a whole new one (little laugh) because uh, you see, I-I, I put the wrong name again. (Little laugh) &#39;cause um...</p><blockquote><p>（扮演瑞秋）嗯，好的。你刚才打电话来要求在入学表上签名。嗯，结果我们需要一个全新的（笑）因为，呃，你看，我，我又错了名字。（笑）因为……</p></blockquote><p><strong>Nurse:</strong> You&#39;re that stupid.</p><blockquote><p>你真蠢。</p></blockquote><p><strong>Monica Geller:</strong> (as Rachel) I am. I&#39;m that stupid. (Little laugh.)</p><blockquote><p>（扮演瑞秋）我是。我真是太蠢了。（笑了笑。）</p></blockquote><p><strong>Rachel Green:</strong> (as Monica) Yeah, and and, I&#39;m just gonna pay for this with a check.</p><blockquote><p>（作为莫妮卡）是的，而且，我只想用支票支付。</p></blockquote><p><strong>Nurse:</strong> Well, you know your insurance will cover that.</p><blockquote><p>嗯，你知道你的保险会赔偿的。</p></blockquote><p><strong>Rachel Green:</strong> (as Monica) Yeah, I know... (mirroring her friend) ..I&#39;m I&#39;m just not that bright either.</p><blockquote><p>（作为莫妮卡）是的，我知道……（镜像她的朋友）…我也不是那么聪明。</p></blockquote><p><em>(The girls escape with a new form.)</em></p><blockquote><p><em>（女孩们以一种新的形式逃跑。）</em></p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Chandler is neglecting the game of Scrabble, for he&#39;s busily drawing on his own childhood in an attempt to help Ross. Marcel chitters about.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，钱德勒忽略了拼字游戏，因为他正忙着画自己的童年，试图帮助罗斯。马塞尔闲聊着。</em></p></blockquote><p><strong>Chandler Bing:</strong> Okay, worst case scenario. Say you never feel like a father.</p><blockquote><p>好吧，最坏的情况。说你从未感觉自己像个父亲。</p></blockquote><p><strong>Ross Geller:</strong> Uh-huh.</p><blockquote><p>嗯。</p></blockquote><p><strong>Chandler Bing:</strong> Say your son never feels connected to you, as one. Say all of his relationships are affected by this.</p><blockquote><p>说你的儿子从来没有感觉到和你是一体的。说他所有的关系都受到影响。</p></blockquote><p><strong>Ross Geller:</strong> Do you have a point?</p><blockquote><p>你说得有道理吗？</p></blockquote><p><strong>Chandler Bing:</strong> You know, you think I would.</p><blockquote><p>你知道，你认为我会的。</p></blockquote><p><em>(Instead of scampering, Marcel stretches his neck as much as possible, and makes an unvoiced noise from his throat.)</em></p><blockquote><p><em>（马塞尔没有蹦蹦跳跳，而是尽量伸长脖子，从喉咙里发出清脆的声音。）</em></p></blockquote><p><strong>Chandler Bing:</strong> What&#39;s up with the simian?</p><blockquote><p>猿猴怎么了？</p></blockquote><p><strong>Ross Geller:</strong> It&#39;s just a fur ball.</p><blockquote><p>只是个皮球。</p></blockquote><p><strong>Chandler Bing:</strong> Okay... (returning to the board) ..whose turn is it?</p><blockquote><p>好吧……（回到董事会）……轮到谁了？</p></blockquote><p><strong>Ross Geller:</strong> Yours, I just got 43 points for &#39;KIDNEY&#39;.</p><blockquote><p>你的，我的“肾”刚得了43分。</p></blockquote><p><strong>Chandler Bing:</strong> No, no, you got zero points for &#39;IDNEY&#39;.</p><blockquote><p>不，不，你的“艾德尼”得了零分。</p></blockquote><p><strong>Ross Geller:</strong> I had a &#39;K&#39;. Where&#39;s where&#39;s my &#39;K&#39;?</p><blockquote><p>我得了个“K”。我的K在哪里？</p></blockquote><p><em>(The unvoiced hissing continues. In alarm, Ross and Chandler look at the monkey, who is now in some distress.)</em></p><blockquote><p><em>（无声的嘶嘶声还在继续。罗斯和钱德勒惊恐地看着这只猴子，它现在正处于某种痛苦之中。）</em></p></blockquote><hr><p>🎬 <em>The Emergency Room, Monica sits with Rachel, who is filling out an honest form at last. Ross and Chandler hurtle in. Little Marcel, wrapped in a fluffy towel, is cradled in Ross&#39;s arms. They dash up to the admissions desk. Ross is frantic.</em></p><blockquote><p>🎬 <em>急诊室，莫妮卡和瑞秋坐在一起，瑞秋终于在填写一份诚实的表格。罗斯和钱德勒冲了进来。小马塞尔裹着毛茸茸的毛巾，抱在罗斯的怀里。他们冲向招生处。罗斯发疯了。</em></p></blockquote><p><strong>Ross Geller:</strong> You&#39;ve got to help me my monkey swallowed a &#39;K&#39;!</p><blockquote><p>你得帮我，我的猴子吞了一个“K”！</p></blockquote><p><em>(Hearing her brother&#39;s voice, Monica gets up to stand behind Chandler, followed by Rachel.)</em></p><blockquote><p><em>（听到哥哥的声音，莫妮卡站起来站在钱德勒后面，后面跟着瑞秋。）</em></p></blockquote><p><strong>Nurse:</strong> (angrily) You go get that animal outta here.</p><blockquote><p>（生气地）你去把那只动物弄出去。</p></blockquote><p><strong>Ross Geller:</strong> No, no you don&#39;t understand the animal hospital is way across town he&#39;s choking I don&#39;t know what else to do.</p><blockquote><p>不，不，你不明白动物医院就在镇对面，他快窒息了，我不知道还能做什么。</p></blockquote><p><strong>Monica Geller:</strong> What&#39;s goin&#39; on?</p><blockquote><p>怎么了？</p></blockquote><p><em>(Ross and Chandler turn at the voice...)</em></p><blockquote><p><em>（罗斯和钱德勒听到这个声音转过身来……）</em></p></blockquote><p><strong>Chandler Bing:</strong> Marcel swallowed a Scrabble tile.</p><blockquote><p>马塞尔吞下了一块拼字瓷砖。</p></blockquote><p><strong>Rachel Green:</strong> Oh.</p><blockquote><p>哦。</p></blockquote><p><em>(..then turn back to the desk when the surprise hits them, and Ross and Chandler whip around once more. Monica and Rachel recoil slightly.)</em></p><blockquote><p><em>（…当惊喜袭来时，他们转身回到桌子旁，罗斯和钱德勒再次挥舞，莫妮卡和瑞秋微微后退。）</em></p></blockquote><p><strong>Nurse:</strong> Excuse me... This hospital is for people!</p><blockquote><p>对不起……这家医院是为人民服务的！</p></blockquote><p><strong>Ross Geller:</strong> Lady, he is people. He has a name, okay? He watches Jeopardy! He he touches himself when nobody&#39;s watching. Please, please have a heart!</p><blockquote><p>女士，他是人。他有名字，好吗？他看着杰帕迪！他在没人看的时候摸自己。请，请有一颗心！</p></blockquote><p><em>(Ross&#39;s vigorous protest is attracting attention.)</em></p><blockquote><p><em>（罗斯的强烈抗议引起了人们的注意。）</em></p></blockquote><p>Dr. Mitchell: I&#39;ll take a look at him.</p><blockquote><p>我去看看他。</p></blockquote><p><em>(Rachel, Monica, Ross and Chandler whip around for a second time, in formation.)</em></p><blockquote><p><em>（瑞秋、莫妮卡、罗斯和钱德勒以队形第二次抽打。）</em></p></blockquote><p>Rachel and **Monica Geller: **Oh, thank you.</p><blockquote><p>瑞秋和<strong>莫妮卡·盖勒：</strong>哦，谢谢。</p></blockquote><p><strong>Monica Geller:</strong> Michael.</p><blockquote><p>迈克尔。</p></blockquote><p>Dr. Mitchell: Rachel.</p><blockquote><p>瑞秋。</p></blockquote><p><strong>Rachel Green:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Monica Geller:</strong> (as Rachel) Monica.</p><blockquote><p>（扮演瑞秋）莫妮卡。</p></blockquote><p><strong>Rachel Green:</strong> (as Monica) Oh.</p><blockquote><p>（扮演莫妮卡）哦。</p></blockquote><p><strong>Monica Geller:</strong> (as Rachel) Hi.</p><blockquote><p>（扮演瑞秋）嗨。</p></blockquote><p><strong>Rachel Green:</strong> (as Monica) Hi.</p><blockquote><p>（扮演莫妮卡）嗨。</p></blockquote><p><em>(Monica smiles to cover her embarrassment, but Rachel sadly looks away...)</em></p><blockquote><p><em>（莫妮卡微笑着掩饰她的尴尬，但瑞秋悲伤地把目光移开了…）</em></p></blockquote><hr><p>🎬 <em>Central Perk, Joey is playing &quot;She Loves Me, She Loves Me Not&quot; with the petals of a flower, alternately looking hopeful and annoyed. Phoebe enters, but not as herself, for she has changed the style of her hair and make-up to match that of her twin sister. She hangs up her coat, revealing her new cardigan. Nervously, she smooths out the identifying garment, approaching Joey who sits next to the main sofa.</em></p><blockquote><p>🎬 <em>中央公园，乔伊在玩“她爱我，她不爱我”带着花瓣，时而充满希望，时而懊恼。菲比进来了，但不像她自己，因为她改变了她的发型和化妆，以匹配她的孪生妹妹。她挂起外套，露出她的新开衫。她紧张地抚平识别服装，走近坐在主沙发旁边的乔伊。</em></p></blockquote><p><strong>Phoebe Buffay:</strong> (as Ursula) Hey.</p><blockquote><p>（扮演乌苏拉）嘿。</p></blockquote><p><strong>Joey Tribbiani:</strong> Urse...</p><blockquote><p>嗯……</p></blockquote><p><em>(Phoebe nods as he stands up in delight.)</em></p><blockquote><p><em>（菲比高兴地站了起来，点了点头。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> ..ah, what&#39;re you doing here? I&#39;ve been trying to call you.</p><blockquote><p>……啊，你在这里干什么？我一直在给你打电话。</p></blockquote><p><strong>Phoebe Buffay:</strong> (as Ursula) Listen, um...</p><blockquote><p>（作为乌苏拉）听着，嗯……</p></blockquote><p><strong>Joey Tribbiani:</strong> No, no, no, don&#39;t say &quot;listen.&quot; I know that &quot;listen.&quot; I&#39;ve said that &quot;listen.&quot;</p><blockquote><p>不，不，不，不要说“听”。我知道“听”。我说过“听”</p></blockquote><p><strong>Phoebe Buffay:</strong> (as Ursula) I&#39;m sorry.</p><blockquote><p>（作为乌苏拉）对不起。</p></blockquote><p><strong>Joey Tribbiani:</strong> I don&#39;t get it. What happened? What about everything you said under the bridge?</p><blockquote><p>我不明白。怎么搞的？你在桥下说的一切怎么样？</p></blockquote><p><em>(Phoebe is almost thrown by this.)</em></p><blockquote><p><em>（菲比几乎被这抛了出去。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> (as Ursula): Yeah, um... (nervously clears her throat) You know you, you should just forget about what I said under the bridge, I was talkin&#39; crazy that night, I was so drunk!</p><blockquote><p>（饰演乌苏拉）：是的，嗯……（紧张地清了清嗓子）你知道的，你应该忘记我在桥下说的话，那天晚上我说得太疯狂了，我喝得太醉了！</p></blockquote><p><strong>Joey Tribbiani:</strong> You don&#39;t drink.</p><blockquote><p>你不喝酒。</p></blockquote><p><strong>Phoebe Buffay:</strong> (as Ursula) That&#39;s right, I don&#39;t... But I was, I was drunk on you!</p><blockquote><p>（饰演厄苏拉）没错，我不……但我是，我是醉在你身上的！</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh, Urse... (He tries to take her in his arms, but she fends him off.)</p><blockquote><p>哦，当然……（他试图把她抱在怀里，但她挡开了。）</p></blockquote><p><strong>Phoebe Buffay:</strong> (as Ursula) Okay, yeah, so it&#39;s not gonna work.</p><blockquote><p>（扮演乌苏拉）好吧，是的，所以这不管用。</p></blockquote><p><strong>Joey Tribbiani:</strong> Why? Is it because I&#39;m friends with Phoebe?</p><blockquote><p>为什么？是因为我和菲比是朋友吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> (as Ursula) If it was, would you stop hanging out with her?</p><blockquote><p>（扮演乌苏拉）如果是的话，你会停止和她在一起吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> (Thinking carefully) no. No, I, I couldn&#39;t do that.</p><blockquote><p>（仔细思考）不，不，我，我不能那样做。</p></blockquote><p><strong>Phoebe Buffay:</strong> (as Ursula) Um, then yes, it&#39;s &#39;cause of Phoebe! So, you know, it&#39;s either her or me.</p><blockquote><p>（饰演厄苏拉）嗯，那是的，这是因为菲比！所以，你知道，不是她就是我。</p></blockquote><p><strong>Joey Tribbiani:</strong> Then, uh, then I&#39;m sorry.</p><blockquote><p>那么，呃，那么我很抱歉。</p></blockquote><p><em>(He sinks to the sofa, saddened by Ursula&#39;s ultimatum, while Phoebe follows, touched by Joey&#39;s good heart.)</em></p><blockquote><p><em>（他坐到沙发上，对乌苏拉的最后通牒感到悲伤，而菲比也跟着，被乔伊的善良感动了。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> (as Ursula) You know... (unconsciously putting a hand on his knee) You&#39;re gonna be really, really hard to get over.</p><blockquote><p>（作为乌苏拉）你知道……（无意识地把手放在他的膝盖上）你真的很难克服。</p></blockquote><p><strong>Joey Tribbiani:</strong> I know...</p><blockquote><p>我知道……</p></blockquote><p><em>(He looks up at her face and Phoebe, slipping out of character, smiles back at him. Joey&#39;s voice becomes soft and warm.)</em></p><blockquote><p><em>（他抬头看着菲比的脸，菲比渐渐失去了个性，对他笑了笑。乔伊的声音变得柔和而温暖。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> I don&#39;t know whether it&#39;s just &#39;cause we&#39;re breakin&#39; up or... what, but you have never looked so beautiful.</p><blockquote><p>我不知道是因为我们分手了还是……什么，但是你从来没有这么漂亮过。</p></blockquote><p><strong>Phoebe Buffay:</strong> Really?</p><blockquote><p>真的吗？</p></blockquote><p><em>(Phoebe smiles, when Joey takes her face in his hands and kisses her. Joey gets up to leave but stops suddenly. Phoebe silently shouts &quot;Oh, whoa!!&quot; to herself, and leans back in the sofa to recover, a hand to her tingling lips. A thoughtful Joey is also feeling his lips, so he hesitates for a moment, then returns for a better view, he thinks again, cocking his head from side to side to regard her profile from various angles, then...)</em></p><blockquote><p><em>（菲比笑了，乔伊用手捂着她的脸吻了她。乔伊起身离开，但突然停了下来。菲比默默地喊道：“哦，哇！！”一只手放在她刺痛的嘴唇上。一个深思熟虑的乔伊也在摸他的嘴唇，所以他犹豫了一会儿，然后回到一个更好的视角，他再次思考，从一边到另一边仰着头，从不同的角度观察她的侧面，然后……）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Pheebs?</p><blockquote><p>菲比？</p></blockquote><p><strong>Phoebe Buffay:</strong> (Automatically) Yeah. Oooh... (she&#39;s sprung.)</p><blockquote><p>（自动地）是的。哦……（她跳起来了。）</p></blockquote><hr><p>🎬 <em>The Hospital, Marcel lies on the operating table while recovering from the anaesthetic, tucked up under a sheet like an infant in a huge bed. Ross sits beside him, as a smiling Chandler, Monica and Rachel look on.</em></p><blockquote><p>🎬 <em>在医院，Marcel从麻醉剂中恢复过来时躺在手术台上，像一个躺在大床上的婴儿一样蜷缩在床单下。Ross坐在他旁边，Chandler、Monica和瑞秋·格林：面带微笑地看着他。</em></p></blockquote><p><strong>Ross Geller:</strong> He looks so tiny.</p><blockquote><p>他看起来很小。</p></blockquote><p><em>(The door bursts open, and Joey and Phoebe rush in.)</em></p><blockquote><p><em>（门突然打开，乔伊和菲比冲了进来。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> We just got the message.</p><blockquote><p>我们刚收到消息。</p></blockquote><p><strong>Phoebe Buffay:</strong> Is he alright?</p><blockquote><p>他还好吗？</p></blockquote><p><strong>Ross Geller:</strong> Yeah. The doctor got the &#39;K&#39; out. He also found an &#39;M&#39; and an &#39;O&#39;.</p><blockquote><p>是的。医生把“K”字去掉了。他还发现了一个“M”和一个“O”。</p></blockquote><p><strong>Chandler Bing:</strong> We think he was trying to spell out &#39;MONKEY.&#39;</p><blockquote><p>我们认为他是想拼出“猴子”</p></blockquote><p><em>(Ross does not approve of Chandler&#39;s daft theory.)</em></p><blockquote><p><em>（罗斯不赞成钱德勒的愚蠢理论。）</em></p></blockquote><p><strong>Ross Geller:</strong> Well, the doctor says he&#39;s gonna be fine, he&#39;s just sleeping now.</p><blockquote><p>嗯，医生说他会好起来的，他现在只是在睡觉。</p></blockquote><p><strong>Chandler Bing:</strong> (Tapping Ross on his shoulder) So, you feel like a dad yet?</p><blockquote><p>（拍拍罗斯的肩膀）那么，你觉得自己像个爸爸了吗？</p></blockquote><p><strong>Ross Geller:</strong> No, why?</p><blockquote><p>没有，为什么？</p></blockquote><p><strong>Chandler Bing:</strong> Hey, come on, you came through, you did what you had to do. That is very dad.</p><blockquote><p>嘿，拜托，你挺过来了，你做了你该做的。那真是太好了，爸爸。</p></blockquote><p><em>(Ross does approve of this, but he&#39;s still not sure. The tiny figure stirs.)</em></p><blockquote><p><em>（罗斯确实赞同这一点，但他仍然不确定。这个小小的身影在颤抖。）</em></p></blockquote><p><strong>Monica Geller:</strong> Oh, look, he&#39;s waking up!</p><blockquote><p>哦，看，他醒了！</p></blockquote><p><strong>Ross Geller:</strong> (Quietly) hey, fella! How you doing?</p><blockquote><p>（平静地）嘿，伙计！你好吗？</p></blockquote><p><em>(All of a sudden, Marcel grabs Ross&#39;s finger with his whole fist, and he squeezes it, so tight, that Ross finally knows what it is to be a father. He looks up at his friends, who smile encouragingly, Rachel tenderly resting her chin upon Monica&#39;s shoulder. Ross realises that Chandler was right and he&#39;s gonna make a great dad!)</em></p><blockquote><p><em>（突然间，马塞尔用整只拳头抓住罗斯的手指，紧紧地捏着，罗斯终于明白了做父亲的意义。他抬头看着朋友们，他们微笑着鼓励他，瑞秋温柔地把下巴靠在莫妮卡的肩膀上。罗斯意识到钱德勒是对的，他会成为一个伟大的父亲！）</em></p></blockquote><p>Closing Credits</p><blockquote><p>片尾字幕</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, everyone except Joey is there. Rachel is looking out of the window and Ross is handing out some Chinese takeout. There&#39;s a small SAP in the corner of the screen.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，除了乔伊，其他人都在。瑞秋看着窗外，罗斯分发一些中国外卖。屏幕的角落里有一个小树液。</em></p></blockquote><p>Ross Geller: Aqui est�. (Here it is!)</p><p><strong>罗斯·盖勒:</strong> 阿奎伊斯特�. （在这里！）</p><p>Monica Geller: �A qui�n pidio el pollo General Tso? (Who ordered General Sal&#39;s chicken?)</p><p><strong>莫妮卡·盖勒:</strong> �魁�n皮迪奥·埃尔·波洛将军？（谁点了萨尔将军的鸡？）</p><p>Chandler Bing: �Pudo aver sido General Tso! (It could&#39;ve been General Sal!)</p><p><strong>钱德勒·宾:</strong> �普多阿弗西多将军曹！（可能是萨尔将军！）</p><p><em>(Rachel points out of the window.)</em></p><blockquote><p><em>（瑞秋指着窗外。）</em></p></blockquote><p>Rachel Green: �Mira, mira, el viejo desnudo est� haciendo el hula hoop! (Look, look, Ugly Naked Guy is doing the hula!)</p><p><strong>瑞秋·格林:</strong> �米拉，米拉，艾尔维乔·德斯努多东部� 哈西恩多呼啦圈！（看，看，丑陋的裸男正在跳草裙舞！）</p><p><em>(The others rush to the window for a look.)</em></p><blockquote><p><em>（其他人冲到窗口看一看。）</em></p></blockquote><p>All:�Ewww! (Ewww!)</p><p>全部：�哇！（www！）</p><p><em>(Joey enters, happy again.)</em></p><blockquote><p><em>（乔伊进来了，又高兴了。）</em></p></blockquote><p>All: �Hola, Joey! (Hi, Joey!)</p><p>全部：�你好，乔伊！（嗨，乔伊！）</p><p>Joey Tribbiani: �Hola, amigos! (Hey, everybody!)</p><p><strong>乔伊·崔比安尼:</strong> �你好，朋友！（大家好！）</p><p><em>(Marcel grabs the remote.)</em></p><blockquote><p><em>（马塞尔抓住遥控器。）</em></p></blockquote><p><strong>Monica Geller:</strong> Mira, Ross, Marcel se llevo el control remoto. (Look, Ross, Marcel&#39;s got the remote.)</p><blockquote><p>米拉，罗斯，马塞尔·塞莱沃，控制室。（看，罗斯，马塞尔有遥控器。）</p></blockquote><p>Ross Geller: �Lo que sucedio es que no le gusta la tele! (The thing is, he doesn`t like the program!)</p><p><strong>罗斯·盖勒:</strong> �你不想在电视上看到我！（问题是，他不喜欢这个节目！）</p><p><em>(Everybody laughs.)</em></p><blockquote><p><em>（大家都笑了。）</em></p></blockquote>',766)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};